#!/usr/bin/env python3
"""
Ambient Intelligence Indexer
Extracts entities, builds relationship graph, generates context packets.
"""

import json
import os
import re
from collections import defaultdict
from pathlib import Path

# Configuration
INPUT_DIR = Path("./input_conversations")
OUTPUT_DIR = Path("./output")
MANIFEST_FILE = Path("./input_manifest.json")

def load_manifest():
    """Load the input manifest."""
    with open(MANIFEST_FILE) as f:
        return json.load(f)

def parse_conversations(input_dir):
    """Parse all conversation files from input directory."""
    conversations = []

    for filepath in sorted(input_dir.glob("*.txt")):
        with open(filepath) as f:
            content = f.read()

        # Extract marker
        marker_match = re.search(r'MARKER:(CONV-\w+-\d+)', content)
        marker = marker_match.group(1) if marker_match else None

        # Extract utterances
        utterances = []
        for line in content.strip().split('\n'):
            if line.startswith('[') and not line.startswith('MARKER:'):
                # Parse: [2025-04-02 09:15] Maya: message
                match = re.match(r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\] (\w+): (.+)', line)
                if match:
                    utterances.append({
                        'timestamp': match.group(1),
                        'speaker': match.group(2),
                        'text': match.group(3)
                    })

        conversations.append({
            'file': filepath.name,
            'marker': marker,
            'utterances': utterances,
            'raw': content
        })

    return conversations

def extract_entities(conversations):
    """Extract people, organizations, projects, and dates from conversations."""
    entities = {
        'people': set(),
        'organizations': set(),
        'projects': set(),
        'dates': set()
    }

    # Known entities from manifest and context
    known_orgs = {'Orion Labs'}
    known_projects = {'Northstar'}

    for conv in conversations:
        for utterance in conv['utterances']:
            text = utterance['text']
            speaker = utterance['speaker']
            timestamp = utterance['timestamp']

            # Extract speaker as person
            entities['people'].add(speaker)

            # Extract date
            date_only = timestamp.split()[0]
            entities['dates'].add(date_only)

            # Look for known organizations
            for org in known_orgs:
                if org in text:
                    entities['organizations'].add(org)

            # Look for known projects
            for proj in known_projects:
                if proj in text:
                    entities['projects'].add(proj)

    return {k: sorted(list(v)) for k, v in entities.items()}

def build_relationship_graph(conversations, entities):
    """Build relationship graph with edge types: works_on, client_of, mentioned_with."""
    edges = []
    seen_edges = set()

    for conv in conversations:
        # Track who is mentioned in each conversation
        mentioned_people = set()

        for utterance in conv['utterances']:
            text = utterance['text']
            speaker = utterance['speaker']
            mentioned_people.add(speaker)

            # works_on: "Northstar is owned by Priya and Sam" -> Priya works_on Northstar, Sam works_on Northstar
            if 'Northstar is owned by' in text:
                # Extract names after "owned by"
                match = re.search(r'Northstar is owned by (.+)', text)
                if match:
                    names_str = match.group(1).strip()
                    # Split by 'and' or comma
                    names = re.split(r'\s+and\s+|\s*,\s*', names_str)
                    for name in names:
                        name = name.strip()
                        if name and name in entities['people']:
                            edge = ('works_on', name, 'Northstar')
                            if edge not in seen_edges:
                                edges.append(edge)
                                seen_edges.add(edge)

            # client_of: "Orion Labs is the client" or "Northstar is related to Orion Labs via the pilot contract"
            if 'Orion Labs is the client' in text or 'Orion Labs' in text and ('client' in text.lower() or 'contract' in text.lower()):
                edge = ('client_of', 'Northstar', 'Orion Labs')
                if edge not in seen_edges:
                    edges.append(edge)
                    seen_edges.add(edge)

    # mentioned_with: people mentioned in same conversation
    for conv in conversations:
        people_in_conv = [u['speaker'] for u in conv['utterances']]
        # Also extract mentioned people from text
        for utterance in conv['utterances']:
            text = utterance['text']
            for person in entities['people']:
                if person in text and person != utterance['speaker']:
                    people_in_conv.append(person)

        unique_people = sorted(set(people_in_conv))
        for i, p1 in enumerate(unique_people):
            for p2 in unique_people[i+1:]:
                edge = ('mentioned_with', p1, p2)
                if edge not in seen_edges:
                    edges.append(edge)
                    seen_edges.add(edge)

    return sorted(edges, key=lambda x: (x[0], x[1], x[2]))

def find_relevant_snippets(conversations, topic):
    """Find conversation snippets relevant to a topic."""
    snippets = []
    topic_keywords = topic.lower().split()

    for conv in conversations:
        for utterance in conv['utterances']:
            text_lower = utterance['text'].lower()
            if any(kw in text_lower for kw in topic_keywords):
                snippets.append({
                    'file': conv['file'],
                    'marker': conv['marker'],
                    'timestamp': utterance['timestamp'],
                    'speaker': utterance['speaker'],
                    'text': utterance['text']
                })

    return snippets

def generate_context_packet(project_name, conversations, entities, edges):
    """Generate Context Packet JSON for the specified project."""
    # Find most recent conversation about deadline shift and client onboarding
    deadline_snippets = find_relevant_snippets(conversations, 'deadline shift change')
    onboarding_snippets = find_relevant_snippets(conversations, 'onboarding blocked')

    # Combine and sort by timestamp
    all_relevant = deadline_snippets + onboarding_snippets
    all_relevant.sort(key=lambda x: x['timestamp'], reverse=True)

    # Get most recent
    most_recent = all_relevant[0] if all_relevant else None

    # Build resolved entities for the project
    resolved_entities = []
    for person in entities['people']:
        # Check if person works on the project
        works_edges = [e for e in edges if e[0] == 'works_on' and e[2] == project_name]
        for edge in works_edges:
            resolved_entities.append({
                'id': edge[1],
                'type': 'person',
                'role': 'owner' if edge[1] in ['Priya', 'Sam'] else 'participant'
            })

    # Add client
    client_edges = [e for e in edges if e[0] == 'client_of' and e[1] == project_name]
    for edge in client_edges:
        resolved_entities.append({
            'id': edge[2],
            'type': 'organization',
            'role': 'client'
        })

    packet = {
        'project': project_name,
        'generated_at': '2025-04-04T00:00:00Z',  # Deterministic timestamp
        'recent_conversations': [
            {
                'file': conv['file'],
                'marker': conv['marker'],
                'summary': ' '.join([u['text'] for u in conv['utterances'][:2]]),
                'entities_mentioned': list(set([u['speaker'] for u in conv['utterances']]))
            }
            for conv in reversed(conversations)
        ],
        'resolved_entities': resolved_entities,
        'relationships': [
            {'type': edge[0], 'source': edge[1], 'target': edge[2]}
            for edge in edges
        ],
        'relevant_history': {
            'deadline_shift': most_recent if most_recent and 'deadline' in most_recent['text'].lower() else deadline_snippets[0] if deadline_snippets else None,
            'client_onboarding': onboarding_snippets[0] if onboarding_snippets else None
        },
        'markers': [conv['marker'] for conv in conversations if conv['marker']]
    }

    return packet

def generate_searchable_summary(conversations, entities, edges):
    """Generate a searchable summary file with conversation snippets."""
    summary = {
        'entities': entities,
        'relationships': [
            {'type': e[0], 'source': e[1], 'target': e[2]}
            for e in edges
        ],
        'conversations': []
    }

    for conv in conversations:
        conv_summary = {
            'file': conv['file'],
            'marker': conv['marker'],
            'dates': list(set([u['timestamp'].split()[0] for u in conv['utterances']])),
            'speakers': list(set([u['speaker'] for u in conv['utterances']])),
            'snippets': conv['utterances']
        }
        summary['conversations'].append(conv_summary)

    # Add index for searchability
    summary['index'] = {
        'by_person': defaultdict(list),
        'by_date': defaultdict(list),
        'by_topic': defaultdict(list)
    }

    for conv in conversations:
        for i, utterance in enumerate(conv['utterances']):
            # Index by person
            summary['index']['by_person'][utterance['speaker']].append({
                'file': conv['file'],
                'marker': conv['marker'],
                'text': utterance['text']
            })
            # Index by date
            date = utterance['timestamp'].split()[0]
            summary['index']['by_date'][date].append({
                'file': conv['file'],
                'marker': conv['marker'],
                'text': utterance['text']
            })
            # Index by topic (keywords)
            text_lower = utterance['text'].lower()
            if 'deadline' in text_lower or 'milestone' in text_lower or 'timeline' in text_lower:
                summary['index']['by_topic']['deadline'].append({
                    'file': conv['file'],
                    'marker': conv['marker'],
                    'text': utterance['text']
                })
            if 'onboarding' in text_lower or 'legal' in text_lower or 'dpa' in text_lower:
                summary['index']['by_topic']['onboarding'].append({
                    'file': conv['file'],
                    'marker': conv['marker'],
                    'text': utterance['text']
                })

    # Convert defaultdicts to regular dicts for JSON serialization
    summary['index']['by_person'] = dict(summary['index']['by_person'])
    summary['index']['by_date'] = dict(summary['index']['by_date'])
    summary['index']['by_topic'] = dict(summary['index']['by_topic'])

    return summary

def main():
    """Main entry point."""
    # Ensure output directory exists
    OUTPUT_DIR.mkdir(exist_ok=True)

    # Load manifest
    manifest = load_manifest()
    project_name = manifest.get('project', 'Northstar')

    # Parse conversations
    conversations = parse_conversations(INPUT_DIR)

    # Extract entities
    entities = extract_entities(conversations)

    # Build relationship graph
    edges = build_relationship_graph(conversations, entities)

    # Generate context packet
    context_packet = generate_context_packet(project_name, conversations, entities, edges)

    # Generate searchable summary
    searchable_summary = generate_searchable_summary(conversations, entities, edges)

    # Write outputs
    with open(OUTPUT_DIR / 'context_packet.json', 'w') as f:
        json.dump(context_packet, f, indent=2)

    with open(OUTPUT_DIR / 'searchable_summary.json', 'w') as f:
        json.dump(searchable_summary, f, indent=2)

    with open(OUTPUT_DIR / 'relationship_graph.json', 'w') as f:
        json.dump({
            'nodes': list(entities['people']) + list(entities['organizations']) + list(entities['projects']),
            'edges': [{'type': e[0], 'source': e[1], 'target': e[2]} for e in edges]
        }, f, indent=2)

    print(f"Indexing complete for project: {project_name}")
    print(f"Entities found: {entities}")
    print(f"Relationships found: {len(edges)}")
    print(f"Outputs written to: {OUTPUT_DIR}")

if __name__ == '__main__':
    main()
