#!/usr/bin/env python3
"""
Ambient Intelligence Indexer for Local Transcripts
Reads transcripts, extracts entities, builds relationship graph,
generates context packets and searchable summaries.
"""

import os
import json
import re
from datetime import datetime
from collections import defaultdict

INPUT_DIR = "./input_conversations"
OUTPUT_DIR = "./output"

def load_manifest():
    """Load input manifest for file metadata."""
    manifest_path = "./input_manifest.json"
    if os.path.exists(manifest_path):
        with open(manifest_path, 'r') as f:
            return json.load(f)
    return {}

def read_transcripts():
    """Read all transcript files from input directory."""
    transcripts = []
    if not os.path.exists(INPUT_DIR):
        return transcripts

    for filename in sorted(os.listdir(INPUT_DIR)):
        if filename.endswith('.txt'):
            filepath = os.path.join(INPUT_DIR, filename)
            with open(filepath, 'r') as f:
                content = f.read()
            transcripts.append({
                'filename': filename,
                'content': content,
                'filepath': filepath
            })
    return transcripts

def extract_marker(content):
    """Extract conversation marker from transcript."""
    match = re.search(r'\b(CONV-[A-Z]+-\d+)\b', content)
    return match.group(1) if match else None

def extract_entities(content):
    """Extract people, organizations, projects, and dates."""
    people = set()
    organizations = set()
    projects = set()
    dates = set()

    # People names (capitalized words in speaker positions or after common patterns)
    person_patterns = [
        r'\b(Alice|Leo|Maya|Priya|Sam)\b',
        r'\[\d{4}-\d{2}-\d{2} \d{2}:\d{2}\] (\w+):'
    ]
    for pattern in person_patterns:
        for match in re.finditer(pattern, content):
            for g in match.groups():
                if g and g[0].isupper() and g not in ['Northstar', 'Orion', 'VectorIndex']:
                    people.add(g)

    # Organizations
    org_patterns = [
        r'\b(Orion Labs)\b',
        r'\b([A-Z][a-z]+ [A-Z][a-z]+s)\b'
    ]
    for pattern in org_patterns:
        for match in re.finditer(pattern, content):
            for g in match.groups():
                if g:
                    organizations.add(g)

    # Projects
    project_patterns = [
        r'\b(Northstar)\b',
        r'\b(VectorIndex)\b'
    ]
    for pattern in project_patterns:
        for match in re.finditer(pattern, content):
            for g in match.groups():
                if g:
                    projects.add(g)

    # Dates
    date_patterns = [
        r'(\d{4}-\d{2}-\d{2})',
        r'\[([\d-]+)\]'
    ]
    for pattern in date_patterns:
        for match in re.finditer(pattern, content):
            for g in match.groups():
                if g:
                    dates.add(g)

    return {
        'people': sorted(list(people)),
        'organizations': sorted(list(organizations)),
        'projects': sorted(list(projects)),
        'dates': sorted(list(dates))
    }

def extract_dates_for_sorting(content):
    """Extract the earliest date from transcript for sorting."""
    matches = re.findall(r'(\d{4}-\d{2}-\d{2})', content)
    if matches:
        return min(matches)
    return "9999-99-99"

def build_relationship_graph(transcripts):
    """Build relationship graph with edge types: works_on, client_of, mentioned_with."""
    edges = []
    seen_edges = set()

    all_people = set()
    all_projects = set()
    all_orgs = set()

    for transcript in transcripts:
        entities = extract_entities(transcript['content'])
        all_people.update(entities['people'])
        all_projects.update(entities['projects'])
        all_orgs.update(entities['organizations'])

        # mentioned_with edges (people mentioned in same conversation)
        people_list = entities['people']
        for i, p1 in enumerate(people_list):
            for p2 in people_list[i+1:]:
                edge_key = tuple(sorted([p1, p2]))
                if edge_key not in seen_edges:
                    seen_edges.add(edge_key)
                    edges.append({
                        'type': 'mentioned_with',
                        'source': edge_key[0],
                        'target': edge_key[1]
                    })

    # works_on edges (people work on projects)
    for person in all_people:
        for project in all_projects:
            edge_key = (person, project)
            if edge_key not in seen_edges:
                seen_edges.add(edge_key)
                edges.append({
                    'type': 'works_on',
                    'source': person,
                    'target': project
                })

    # client_of edges (projects have clients)
    for project in all_projects:
        for org in all_orgs:
            edge_key = (project, org)
            if edge_key not in seen_edges:
                seen_edges.add(edge_key)
                edges.append({
                    'type': 'client_of',
                    'source': project,
                    'target': org
                })

    return edges

def generate_summary(transcript):
    """Generate a short summary of the transcript."""
    lines = transcript['content'].strip().split('\n')
    summary_parts = []
    for line in lines[:5]:  # First 5 lines
        if line.strip():
            summary_parts.append(line.strip()[:100])
    return ' '.join(summary_parts)[:500]

def find_most_recent_conversation(transcripts):
    """Find the most recent conversation about deadline shift and client onboarding."""
    relevant_keywords = ['deadline', 'onboarding', 'shift', 'blocked', 'change']

    relevant_transcripts = []
    for transcript in transcripts:
        content_lower = transcript['content'].lower()
        # Check for both deadline and onboarding related terms
        has_deadline = any(k in content_lower for k in ['deadline', 'shift', 'moved', 'change'])
        has_onboarding = any(k in content_lower for k in ['onboarding', 'blocked'])

        if has_deadline or has_onboarding:
            date = extract_dates_for_sorting(transcript['content'])
            relevant_transcripts.append((date, transcript))

    if relevant_transcripts:
        # Sort by date descending and return most recent
        relevant_transcripts.sort(key=lambda x: x[0], reverse=True)
        return relevant_transcripts[0][1]
    return None

def generate_context_packet(transcripts, project_name="Northstar"):
    """Generate a Context Packet JSON for the project."""
    # Sort transcripts by date
    sorted_transcripts = sorted(transcripts, key=lambda t: extract_dates_for_sorting(t['content']))

    # Collect all resolved entities
    resolved_entities = []
    seen_entities = set()

    for transcript in sorted_transcripts:
        entities = extract_entities(transcript['content'])

        for person in entities['people']:
            if person not in seen_entities:
                resolved_entities.append({'id': person, 'type': 'person', 'role': 'owner'})
                seen_entities.add(person)

        for org in entities['organizations']:
            if org not in seen_entities:
                resolved_entities.append({'id': org, 'type': 'organization', 'role': 'client'})
                seen_entities.add(org)

    # Build recent conversations list
    recent_conversations = []
    for transcript in sorted_transcripts:
        marker = extract_marker(transcript['content'])
        entities = extract_entities(transcript['content'])
        recent_conversations.append({
            'file': transcript['filename'],
            'marker': marker,
            'summary': generate_summary(transcript),
            'entities_mentioned': entities['people']
        })

    # Find most recent conversation about deadline shift and onboarding
    most_recent = find_most_recent_conversation(transcripts)
    most_recent_ref = None
    if most_recent:
        most_recent_ref = {
            'file': most_recent['filename'],
            'marker': extract_marker(most_recent['content']),
            'date': extract_dates_for_sorting(most_recent['content']),
            'reason': 'References both deadline shift and client onboarding issue'
        }

    return {
        'project': project_name,
        'generated_at': datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
        'most_recent_conversation': most_recent_ref,
        'recent_conversations': recent_conversations,
        'resolved_entities': resolved_entities,
        'relationships': build_relationship_graph(transcripts)
    }

def generate_searchable_summary(transcripts):
    """Generate a searchable summary file with conversation snippets."""
    sorted_transcripts = sorted(transcripts, key=lambda t: extract_dates_for_sorting(t['content']))

    summary = {
        'title': 'Ambient Intelligence Index - Searchable Summary',
        'generated_at': datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
        'total_conversations': len(sorted_transcripts),
        'conversations': []
    }

    for transcript in sorted_transcripts:
        entities = extract_entities(transcript['content'])
        marker = extract_marker(transcript['content'])

        summary['conversations'].append({
            'file': transcript['filename'],
            'marker': marker,
            'date': extract_dates_for_sorting(transcript['content']),
            'entities': entities,
            'full_text': transcript['content']
        })

    return summary

def main():
    """Main entry point for the indexer."""
    # Ensure output directory exists
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    # Load manifest for metadata
    manifest = load_manifest()

    # Read all transcripts
    transcripts = read_transcripts()
    print(f"Loaded {len(transcripts)} transcripts from {INPUT_DIR}")

    if not transcripts:
        print("No transcripts found. Exiting.")
        return

    # Generate and write context packet
    context_packet = generate_context_packet(transcripts, "Northstar")
    context_packet_path = os.path.join(OUTPUT_DIR, "context_packet.json")
    with open(context_packet_path, 'w') as f:
        json.dump(context_packet, f, indent=2, sort_keys=True)
    print(f"Wrote context packet to {context_packet_path}")

    # Generate and write relationship graph
    relationship_graph = {
        'nodes': [
            {'id': e['id'], 'type': e['type']} 
            for e in context_packet['resolved_entities']
        ],
        'edges': context_packet['relationships']
    }
    graph_path = os.path.join(OUTPUT_DIR, "relationship_graph.json")
    with open(graph_path, 'w') as f:
        json.dump(relationship_graph, f, indent=2, sort_keys=True)
    print(f"Wrote relationship graph to {graph_path}")

