            filepath = os.path.join(INPUT_DIR, filename)
            with open(filepath, "r") as f:
                content = f.read()
            transcripts.append({"filename": filename, "content": content, "filepath": filepath})
    return transcripts

def extract_marker(content):
    match = re.search(r"\\b(CONV-[A-Z]+-\\d+)\\b", content)
    return match.group(1) if match else None

def extract_entities(content):
    people = set()
    organizations = set()
    projects = set()
    dates = set()
    person_patterns = [r"\\b(Alice|Leo|Maya|Priya|Sam)\\b", r"\\[\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}\\] (\\w+):"]
    for pattern in person_patterns:
