    print(f"Wrote context packet to {context_packet_path}")
    relationship_graph = {"nodes": [{"id": e["id"], "type": e["type"]} for e in context_packet["resolved_entities"]], "edges": context_packet["relationships"]}
    graph_path = os.path.join(OUTPUT_DIR, "relationship_graph.json")
    with open(graph_path, "w") as f:
        json.dump(relationship_graph, f, indent=2, sort_keys=True)
    print(f"Wrote relationship graph to {graph_path}")
    searchable_summary = generate_searchable_summary(transcripts)
    summary_path = os.path.join(OUTPUT_DIR, "searchable_summary.json")
    with open(summary_path, "w") as f:
        json.dump(searchable_summary, f, indent=2, sort_keys=True)
    print(f"Wrote searchable summary to {summary_path}")
    print("\\nIndexing complete!")

if __name__ == "__main__":
    main()
